function minutosDeViaje(paradas, minutosPorParada) {
  if (paradas < 0 || minutosPorParada < 0) {
    return "Entrada inválida";
  }
  return paradas * minutosPorParada;
}

function costoDelViaje(paradas, minutosPorParada, tarifaPorMinuto) {
  if (paradas < 0 || minutosPorParada < 0 || tarifaPorMinuto < 0) {
    return "Entrada inválida";
  }
  return minutosDeViaje(paradas, minutosPorParada) * tarifaPorMinuto;
}
